cat <<'EOF' > app/views/searches/show.html.erb
<% @page_title = @search.present? ? "Search: #{@search.query}" : "Search" %>
<% turbo_exempts_page_from_cache %>

<% content_for :header do %>
  <div class="header__actions header__actions--start">
    <%= back_link_to "Home", root_path, "keydown.left@document->hotkey#click keydown.esc@document->hotkey#click" %>
  </div>

  <h1 class="header__title" data-bridge--title-target="header">Search</h1>
<% end %>

<section class="search">
  <%= form_with url: search_path, method: :get, class: "search__form", data: { turbo_frame: "search_results", turbo_action: "advance" } do |form| %>
    <%= form.search_field :q, value: @search.query, placeholder: "Search cards by title, description, or comment…", class: "input search__input", autofocus: @search.blank?, autocorrect: "off", autocomplete: "off" %>
    <%= form.button type: :submit, class: "btn btn--reversed" do %>
      <%= icon_tag "search" %>
      <span>Search</span>
    <% end %>
  <% end %>

  <%= turbo_frame_tag :search_results do %>
    <% if @search.present? %>
      <% if @page.records.any? %>
        <div class="search__results">
          <%= with_automatic_pagination :search_results_paginated_container, @page do %>
            <%= render partial: "searches/card", collection: @page.records, as: :card, locals: { search: @search } %>
          <% end %>
        </div>
      <% else %>
        <div class="blank-slate align-self-center">No cards match “<%= @search.query %>”</div>
      <% end %>
    <% end %>
  <% end %>
</section>
EOF

