cat <<'EOF' > app/views/searches/_card.html.erb
<%= card_article_tag card, class: "card search__card", tabindex: 0 do %>
  <%= link_to card_path(card), class: "card__link", title: card_title_tag(card), data: { turbo_frame: "_top" } do %>
    <span class="for-screen-reader"><%= card.title %></span>
  <% end %>

  <header class="card__header">
    <%= render "cards/display/preview/board", card: card %>
    <%= render "cards/display/preview/tags", card: card %>
    <%= render "cards/display/preview/steps", card: card %>
    <%= icon_tag "attachment", class: "card__attachments-indicator translucent" if card.has_attachments? %>

    <% if card.triaged? %>
      <span class="btn justify-start card__column-name card__column-name--current txt-uppercase min-width max-width">
        <span class="overflow-ellipsis"><%= card.column.name %></span>
      </span>
    <% end %>
  </header>

  <div class="card__body flex-column">
    <div class="card__content">
      <h3 class="card__title">
        <%= highlight_card_title(card, search.terms) %>
      </h3>

      <% if description_excerpt = search_description_excerpt(card, search.terms) %>
        <p class="search__excerpt"><%= description_excerpt %></p>
      <% end %>

      <% matching_comments = search_matching_comments(card, search.terms) %>
      <% if matching_comments.any? %>
        <div class="search__comments">
          <% matching_comments.each do |comment, comment_excerpt| %>
            <%= link_to comment, class: "search__comment", data: { turbo_frame: "_top" } do %>
              <span class="search__comment-author"><%= comment.creator.familiar_name %></span>
              <span class="search__comment-excerpt"><%= comment_excerpt %></span>
            <% end %>
          <% end %>
        </div>
      <% end %>
    </div>

    <%= render "cards/display/common/stamp", card: card %>
  </div>

  <footer class="card__footer flex gap-half">
    <%= render "cards/display/preview/meta", card: card, preview: true %>
    <div class="card__counts">
      <%= render "cards/display/preview/boosts", card: card %>
      <%= render "cards/display/preview/comments", card: card %>
    </div>
    <%= render "cards/display/common/background", card: card %>
  </footer>
<% end %>
EOF

